R=[]
def region(id,name,short,loc,fun,patient,myth,clinical,nets,sources,view):
 R.append(dict(id=id,name=name,short=short,location=loc,function=fun,patient=patient,myth=myth,clinical=clinical,networks=nets.split(),sources=sources.split(),view=view,level='Estabelecida',uncertainty='Topografia geral é bem descrita. Funções resultam de redes; este esquema não delimita áreas de uma pessoa nem permite inferir diagnóstico.'))
region('frontal','Lobo frontal','Frontal','Anterior ao sulco central.','Participa de ação, planejamento e controle em redes.','Planejar e agir envolvem muitas áreas trabalhando juntas.','Não é um chefe racional isolado.','Lesões podem alterar ação e organização; contexto e extensão importam.','executive attention','lateral control','lateral')
region('parietal','Lobo parietal','Parietal','Posterior ao sulco central, acima do temporal.','Integra informação sensorial e espacial.','Ajuda a orientar o corpo e a atenção no espaço.','Não é apenas o centro do tato.','Lesões podem afetar atenção espacial e habilidades aprendidas.','attention executive','lateral control','lateral')
region('temporal','Lobo temporal','Temporal','Abaixo do sulco lateral.','Participa de audição, linguagem e memória por circuitos distintos.','Reconhecer sons, significados e lembranças depende de conexões.','Memória não fica guardada em uma única gaveta.','Alterações de linguagem e memória dependem das regiões e conexões afetadas.','memory threat','lateral memory aphasia','lateral')
region('occipital','Lobo occipital','Occipital','Polo posterior do hemisfério.','Processamento visual em parceria com outras áreas.','Ver envolve interpretar sinais; não é uma fotografia perfeita.','Os olhos não explicam sozinhos a visão.','Lesões podem comprometer campos visuais; avaliação específica é necessária.','attention','lateral','lateral')
region('motor','Córtex motor primário','Motor','Giro pré-central, antes do sulco central.','Contribui para comandos de movimento voluntário.','Mover-se depende de cérebro, medula, músculos e experiência.','Não controla sozinho toda a ação.','Fraqueza súbita exige atenção médica imediata.','executive','lateral stroke','lateral')
region('sensory','Córtex somatossensorial primário','Sensitivo','Giro pós-central, atrás do sulco central.','Processa informações somáticas em mapas distribuídos.','O cérebro integra sinais do corpo para perceber toque e posição.','Dor não pode ser lida como um único ponto sensorial.','Perdas sensitivas requerem contexto neurológico.','interoception attention','lateral pain','lateral')
region('dlpfc','Pré-frontal dorsolateral','CPF lateral','Porção lateral superior do córtex pré-frontal.','Participa da manutenção de metas e do controle de tarefas.','Sustentar uma meta exige coordenação e pode ficar mais difícil sob sobrecarga.','Não é um medidor de força de vontade.','Dificuldades executivas ocorrem em vários quadros; não localizam uma lesão por si.','executive attention','control','lateral')
region('vmpfc','Pré-frontal ventromedial','CPF medial','Porção medial inferior do lobo frontal.','Participa de avaliação contextual e aprendizagem de segurança.','O que parece seguro muda com experiências e contexto.','Não é um botão que desliga a amígdala.','Associações experimentais não indicam alvos individuais de tratamento.','threat reward default','extinction fear','medial')
region('ofc','Córtex orbitofrontal','Orbitofrontal','Face inferior frontal, acima das órbitas.','Participa da avaliação de resultados e ajuste de escolhas.','Nossas escolhas levam em conta resultados e circunstâncias.','Não é o lugar da moralidade.','Alterações de escolhas não demonstram dano orbitofrontal.','reward executive','anatomy reward','inferior')
region('insula','Ínsula','Ínsula','Profunda no sulco lateral; exposta nos cortes.','Integra sinais corporais e informações relevantes em redes.','Sentir o corpo envolve interpretar sinais junto com o que está acontecendo.','Não é um centro exclusivo da empatia.','Percepção corporal e sofrimento não têm marcador único nessa região.','salience interoception autonomic','anatomy intero seeley','coronalA')
region('acc','Córtex cingulado anterior','Cíngulo anterior','Face medial, ao redor da porção anterior do corpo caloso.','Participa de saliência, controle e integração autonômica.','Atenção, corpo e ação conversam entre si.','Atividade aqui não revela um sentimento específico.','Achados transdiagnósticos são de grupos e não diagnosticam indivíduos.','salience autonomic executive','seeley autonomic transdiag','medial')
region('pcc','Cíngulo posterior / precuneus','Cíngulo posterior','Face medial posterior; regiões próximas, não idênticas.','Participa de redes associadas ao processamento interno.','Mesmo em repouso, o cérebro continua ativo.','Rede padrão não é sinônimo de ruminação.','Participação em uma rede não determina uma condição clínica.','default memory','dmn yeo','medial')
region('hippocampus','Hipocampo','Hipocampo','Temporal medial, profundo; posterior à amígdala.','Importante para formar memórias declarativas em redes.','Lembrar é reconstruir; uma lembrança não funciona como um vídeo.','Não armazena todas as memórias.','Comprometimento pode afetar novas memórias; sono e atenção também influem no desempenho.','memory threat','memory ventral sleep-memory','coronalP')
region('amygdala','Complexo amigdaloide','Amígdala','Temporal medial anterior, à frente do hipocampo.','Participa de aprendizagem de relevância e de respostas defensivas.','Aprender o que é importante envolve uma rede, não uma parte isolada.','Não é o centro do medo nem o cérebro reptiliano.','Relacionar resposta defensiva e medo consciente é objeto de debate.','threat salience autonomic','fear fear-debate extinction','coronalA')
region('thalamus','Tálamo','Tálamo','Diencéfalo, acima do hipotálamo.','Integra circuitos corticais, sensoriais e de controle.','Informações circulam por circuitos com várias estações.','Não é um simples relé passivo.','Alterações podem afetar múltiplas funções; núcleos têm papéis diferentes.','attention executive','anatomy control','medial')
region('hypothalamus','Hipotálamo','Hipotálamo','Abaixo do tálamo, junto ao terceiro ventrículo.','Participa de regulação homeostática, autonômica e hormonal.','Corpo e cérebro se ajustam continuamente às demandas.','Cortisol não é uma substância sempre ruim.','Eixo de estresse inclui hipófise e adrenais, fora deste desenho cerebral.','stress autonomic','anatomy stress','medial')
region('basal','Núcleos da base','Núcleos da base','Núcleos profundos; o desenho destaca estriado e região palidal.','Participam da seleção de ações e aprendizagem.','Ações habituais e novas escolhas dependem de circuitos diferentes que cooperam.','Dopamina não equivale a prazer ou caráter.','Circuitos corticoestriatais são relevantes para movimento; ligações psiquiátricas não são diagnóstico.','reward executive','anatomy reward parkinson','coronalA')
region('cerebellum','Cerebelo','Cerebelo','Posterior ao tronco, abaixo dos lobos occipitais.','Coordenação e aprendizagem motora; circuitos também se conectam a áreas associativas.','Ajustar movimentos envolve aprender com diferenças entre intenção e resultado.','Não é apenas um órgão de equilíbrio.','Mudanças súbitas de coordenação requerem avaliação urgente.','executive','anatomy stroke','lateral')
region('brainstem','Tronco encefálico','Tronco','Mesencéfalo, ponte e bulbo; anterior ao cerebelo.','Abriga vias e núcleos importantes para vigília e regulação corporal.','Funções essenciais do corpo dependem de muitos circuitos integrados.','Não é um cérebro primitivo separado do restante.','Lesões podem comprometer funções vitais; este atlas não avalia consciência.','autonomic stress reward','anatomy autonomic','medial')
region('callosum','Corpo caloso','Corpo caloso','Feixe de substância branca entre hemisférios.','Conecta regiões corticais dos dois hemisférios.','Os dois lados do cérebro trabalham em cooperação.','Pessoas não são de cérebro esquerdo ou direito.','Conexão física é diferente de correlação de sinais na ressonância funcional.','executive','anatomy ventricles','medial')
region('ventricles','Sistema ventricular','Ventrículos','Cavidades internas; laterais, terceiro e quarto ventrículos.','Contêm líquido cefalorraquidiano e se comunicam.','O cérebro é protegido por estruturas e líquido ao seu redor e dentro dele.','Ventrículos não são centros de pensamentos ou emoções.','Tamanho em imagens exige interpretação médica; aqui não há medida nem escala.','','ventricles','coronalP')

N=[]
